/// <summary>
/// DebuC 21.08.23
/// </summary>
static void saveEnums()
{
    #AviFiles
    NDXEnums        nDXEnums;

    Dictionary      dictionary;
    DictEnum        dictEnum;
    int             i, j;
    utcdatetime     dateTimeStamp = DateTimeUtil::utcNow();
    NDXEnumName            nDXEnumName;
    NDXEnumNameElement     nDXEnumNameElement;
    NDXEnumLabelElement    nDXEnumLabelElement;
    NDXEnumValue           nDXEnumValue;
    NDXEnumLabel           nDXEnumLabel;
    ;

    dictionary = new Dictionary();
    for (i=1; i<=dictionary.enumCnt(); i++)
    {
        dictEnum    = new DictEnum(dictionary.enumCnt2Id(i));
        if (!dictEnum)
        {
            continue;
        }

        for (j=0; j<=dictEnum.values()-1; j++)
        {
            ttsbegin;
            nDXEnumName            = dictEnum.name();
            nDXEnumLabel           = dictEnum.label();
            nDXEnumNameElement     = dictEnum.index2Symbol(j);
            nDXEnumValue           = dictEnum.index2Value(j);
            nDXEnumLabelElement    = dictEnum.index2Label(j);
            nDXEnums   = NDXEnums::find(nDXEnumName, nDXEnumNameElement, nDXEnumValue, true);

            if (!nDXEnums)
            {
                nDXEnums.EnumName          = nDXEnumName;
                nDXEnums.EnumNameElement   = nDXEnumNameElement;
                nDXEnums.EnumValue         = nDXEnumValue;
            }
            nDXEnums.EnumLabel         = NDXEnumLabel;
            nDXEnums.EnumLabelElement  = nDXEnumLabelElement;
            nDXEnums.UpdatedUTC        = dateTimeStamp;
            if (nDXEnums.validateWrite())
            {
                nDXEnums.write();
            }
            ttscommit;
        }
    }

    // ungültige Einträge löschen
    delete_from nDXEnums
    where   nDXEnums.Manuell == NoYes::No
        &&  nDXEnums.UpdatedUTC != dateTimeStamp;
}

/// <summary>
/// DebuC 21.08.23
/// </summary>
/// <param name = "args">Args</param>
static void main(Args args = null)
{
    ;
    NDXReflection::saveEnums();
}
